from typing import List

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        n = len(circles)
        parent = list(range(n + 4))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        L, B, R, T = n, n + 1, n + 2, n + 3

        def clamp(v, lo, hi):
            return min(max(v, lo), hi)

        # Check if origin or corner is covered by a circle
        for x, y, r in circles:
            if x * x + y * y <= r * r:
                return False
            dx = x - xCorner
            dy = y - yCorner
            if dx * dx + dy * dy <= r * r:
                return False

        def touches_L(x, y, r):
            dx = x
            dy = y - clamp(y, 0, yCorner)
            return dx * dx + dy * dy <= r * r

        def touches_B(x, y, r):
            dx = x - clamp(x, 0, xCorner)
            dy = y
            return dx * dx + dy * dy <= r * r

        def touches_R(x, y, r):
            dx = x - xCorner
            dy = y - clamp(y, 0, yCorner)
            return dx * dx + dy * dy <= r * r

        def touches_T(x, y, r):
            dx = x - clamp(x, 0, xCorner)
            dy = y - yCorner
            return dx * dx + dy * dy <= r * r

        for i, (x, y, r) in enumerate(circles):
            if touches_L(x, y, r):
                union(i, L)
            if touches_B(x, y, r):
                union(i, B)
            if touches_R(x, y, r):
                union(i, R)
            if touches_T(x, y, r):
                union(i, T)

        for i in range(n):
            xi, yi, ri = circles[i]
            for j in range(i + 1, n):
                xj, yj, rj = circles[j]
                dx = xi - xj
                dy = yi - yj
                if dx * dx + dy * dy <= (ri + rj) * (ri + rj):
                    union(i, j)

        rB, rR = find(B), find(R)
        rL, rT = find(L), find(T)
        if rB == rL or rB == rT or rR == rL or rR == rT:
            return False
        return True
