class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        X, Y = xCorner, yCorner
        n = len(circles)
        parent = list(range(n + 2))
        A = n      # arc: left + top edges
        B = n + 1  # arc: bottom + right edges

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        def touches(px, py, x, y, r):
            return (px - x) * (px - x) + (py - y) * (py - y) <= r * r

        for i, (x, y, r) in enumerate(circles):
            cy = min(max(y, 0), Y)
            cx = min(max(x, 0), X)
            # left edge: (0, cy)
            if touches(0, cy, x, y, r):
                union(i, A)
            # top edge: (cx, Y)
            if touches(cx, Y, x, y, r):
                union(i, A)
            # bottom edge: (cx, 0)
            if touches(cx, 0, x, y, r):
                union(i, B)
            # right edge: (X, cy)
            if touches(X, cy, x, y, r):
                union(i, B)

        for i in range(n):
            x1, y1, r1 = circles[i]
            for j in range(i + 1, n):
                x2, y2, r2 = circles[j]
                dx = x1 - x2
                dy = y1 - y2
                rs = r1 + r2
                if dx * dx + dy * dy <= rs * rs:
                    union(i, j)

        return find(A) != find(B)
