class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        n = len(circles)
        # nodes: 0..n-1 circles, n = wall T (left+top), n+1 = wall R (bottom+right)
        parent = list(range(n + 2))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        T = n
        R = n + 1

        def seg_dist2(px, py, ax, ay, bx, by):
            # squared distance from point to segment [a,b] (axis-aligned)
            dx = bx - ax
            dy = by - ay
            L2 = dx * dx + dy * dy
            if L2 == 0:
                return (px - ax) ** 2 + (py - ay) ** 2
            t = ((px - ax) * dx + (py - ay) * dy) / L2
            if t < 0:
                t = 0
            elif t > 1:
                t = 1
            cx = ax + t * dx
            cy = ay + t * dy
            return (px - cx) ** 2 + (py - cy) ** 2

        for i, (x, y, r) in enumerate(circles):
            r2 = r * r
            # wall T: left edge (0,0)-(0,yCorner), top edge (0,yCorner)-(xCorner,yCorner)
            if (seg_dist2(x, y, 0, 0, 0, yCorner) <= r2 or
                    seg_dist2(x, y, 0, yCorner, xCorner, yCorner) <= r2):
                union(i, T)
            # wall R: bottom edge (0,0)-(xCorner,0), right edge (xCorner,0)-(xCorner,yCorner)
            if (seg_dist2(x, y, 0, 0, xCorner, 0) <= r2 or
                    seg_dist2(x, y, xCorner, 0, xCorner, yCorner) <= r2):
                union(i, R)

        for i in range(n):
            for j in range(i + 1, n):
                x1, y1, r1 = circles[i]
                x2, y2, r2_ = circles[j]
                d2 = (x1 - x2) ** 2 + (y1 - y2) ** 2
                if d2 <= (r1 + r2_) ** 2:
                    union(i, j)

        return find(T) != find(R)
