        L, T, R, B = n, n + 1, n + 2, n + 3

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for i, (x, y, r) in enumerate(circles):
            # origin or far corner inside circle
            if x * x + y * y <= r * r:
                return False
            dx, dy = x - xCorner, y - yCorner
            if dx * dx + dy * dy <= r * r:
                return False
            # left wall x=0, y in [0,yC]
            cy = min(max(y, 0), yCorner)
            if x * x + (y - cy) ** 2 <= r * r:
                union(i, L)
            # bottom wall y=0, x in [0,xC]
            cx = min(max(x, 0), xCorner)
            if (x - cx) ** 2 + y * y <= r * r:
                union(i, B)
            # right wall x=xC
            if (x - xCorner) ** 2 + (y - cy) ** 2 <= r * r:
                union(i, R)
            # top wall y=yC
            if (x - cx) ** 2 + (y - yCorner) ** 2 <= r * r:
                union(i, T)

        for i in range(n):
            xi, yi, ri = circles[i]
            for j in range(i + 1, n):
                xj, yj, rj = circles[j]
                if (xi - xj) ** 2 + (yi - yj) ** 2 <= (ri + rj) ** 2:
                    union(i, j)

        pairs = [(L, B), (L, R), (T, B), (T, R)]
        for a, b in pairs:
            if find(a) == find(b):
                return False
        return True

